from jsonb_to_recordset($json$[{"id":"che-ek-173","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Electrolysis of molten sodium chloride yields, as the electrode products,","options":["sodium metal at the cathode and chlorine gas at the anode","hydrogen at the cathode and oxygen at the anode","chlorine at both electrodes","solid NaCl crystals on the anode"],"answer_index":0,"explanation":"In the melt the only ions are Na$^+$ and Cl$^-$, so Na and Cl$_2$ are discharged.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-174","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"When aqueous CuSO$_4$ is electrolysed with copper electrodes, the anode reaction is","options":["dissolution of copper metal as Cu$^{2+}$","evolution of oxygen from water","deposition of solid sulphur","reduction of Cu$^{2+}$ to Cu"],"answer_index":0,"explanation":"A copper anode is oxidised in preference to water or sulphate, so the anode loses mass while copper plates at the cathode.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-175","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Preferential discharge at an electrode is decided by","options":["the ion that is most easily reduced (or oxidised) under the prevailing conditions","the ion present in the largest catalogue mass only","the colour of the electrolyte","the cell constant of the vessel"],"answer_index":0,"explanation":"The couple with the more favourable discharge potential (including overvoltage and concentration) is liberated first.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-176","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The quantity of electricity $Q$ that flows in time $t$ at a steady current $I$ is","options":["$Q = It$","$Q = I/t$","$Q = t/I$","$Q = I + t$"],"answer_index":0,"explanation":"Current is charge per unit time, so charge is the product $It$ (amperes × seconds = coulombs).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-177","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Electrolysis of acidified water with inert electrodes liberates","options":["hydrogen at the cathode and oxygen at the anode, in a 2 : 1 volume ratio","oxygen at the cathode and hydrogen at the anode","only hydrogen, because oxygen stays dissolved","chlorine and sodium"],"answer_index":0,"explanation":"2 H$_2$O → 2 H$_2$ + O$_2$. Two moles of hydrogen appear for each mole of oxygen.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-178","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"During electrolysis the cathode is still defined as the electrode at which","options":["reduction occurs","oxidation occurs","the external battery is connected to earth","no ion can be discharged"],"answer_index":0,"explanation":"The cathode/anode labels follow the chemistry (reduction/oxidation), not the galvanic sign convention.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-179","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Electrochemical equivalent $Z$ of a substance equals","options":["molar mass divided by $nF$","molar mass multiplied by $nF$","$nF$ alone","cell constant divided by $\\kappa$"],"answer_index":0,"explanation":"$m = ZQ$ with $Z = M/(nF)$, so $Z$ is the mass liberated by one coulomb.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-180","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"To deposit one mole of aluminium from Al$^{3+}$ one must pass a charge of","options":["$3F$","$1F$","$2F$","$F/3$"],"answer_index":0,"explanation":"Each Al$^{3+}$ ion consumes three electrons, so 1 mol Al requires $3 \\times 96500\\ \\mathrm{C}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-181","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A 1.0 A current sent for 965 s through aqueous AgNO$_3$ deposits silver (Ag = 108) amounting to","options":["$1.08\\ \\mathrm{g}$","$10.8\\ \\mathrm{g}$","$0.108\\ \\mathrm{g}$","$108\\ \\mathrm{g}$"],"answer_index":0,"explanation":"$m = (108/96500) \\times 1.0 \\times 965 = 1.08\\ \\mathrm{g}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-182","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"How many coulombs are required to plate 0.50 mol of copper from Cu$^{2+}$?","options":["$96500\\ \\mathrm{C}$","$48250\\ \\mathrm{C}$","$193000\\ \\mathrm{C}$","$0.50\\ \\mathrm{C}$"],"answer_index":0,"explanation":"Each mole of Cu$^{2+}$ needs 2 mol electrons, so 0.50 mol needs $1.0\\,F = 96500\\ \\mathrm{C}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-183","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A 2.0 A current flows for 965 s through acidified water. The STP volume of H$_2$ evolved is nearest","options":["$0.224\\ \\mathrm{L}$","$22.4\\ \\mathrm{L}$","$0.112\\ \\mathrm{L}$","$2.24\\ \\mathrm{L}$"],"answer_index":0,"explanation":"$Q = 1930\\ \\mathrm{C} = 0.020\\ \\mathrm{mol\\ e^-}$; $2\\,e^- \\to 1\\ \\mathrm{H_2}$, so $0.010\\ \\mathrm{mol} = 0.224\\ \\mathrm{L}$ at STP.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-184","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"To deposit 0.216 g of Ag (Ag = 108) from AgNO$_3$ at 0.50 A, the time required is","options":["386 s","193 s","965 s","1930 s"],"answer_index":0,"explanation":"$Q = m \\times F / M = 0.216 \\times 96500 / 108 = 193\\ \\mathrm{C}$; $t = Q/I = 193/0.50 = 386\\ \\mathrm{s}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
